import{_ as t,c as _,a2 as e,o as a}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"学习易经之类的文化，最终的目的是什么，自渡还是渡人?","description":"","frontmatter":{},"headers":[],"relativePath":"传统文化/易经/学习易经之类的文化，最终的目的是什么，自渡还是渡人.md","filePath":"传统文化/易经/学习易经之类的文化，最终的目的是什么，自渡还是渡人.md"}'),r={name:"传统文化/易经/学习易经之类的文化，最终的目的是什么，自渡还是渡人.md"};function o(n,p,s,c,i,d){return a(),_("div",null,p[0]||(p[0]=[e('<h1 id="学习易经之类的文化-最终的目的是什么-自渡还是渡人" tabindex="-1">学习易经之类的文化，最终的目的是什么，自渡还是渡人? <a class="header-anchor" href="#学习易经之类的文化-最终的目的是什么-自渡还是渡人" aria-label="Permalink to &quot;学习易经之类的文化，最终的目的是什么，自渡还是渡人?&quot;">​</a></h1><p>看站在什么维度去看易经。易经有三易，不易，简易，变易。不易是体，简易是用，变易是相，体相用三则一，一则三。</p><p>不易就是无思也，无为也，寂然不动，感而随通天下之本体，就是真心。变易就是八八六十四卦，宇宙万法，万法者就是心识，展现出来就是卦相。</p><p><strong>卦相就是挂着的相，是虚幻的，生灭的，无常的，变化的，所以不要执着。以卦相明真心</strong>。</p><p>凡所有相皆是虚妄，只要是有相的东西，都不可以执着，因为是毕竟空。</p><p>万法一直在变，卦相也一直在变，可是有一个不变的易之本体，就是每个人的真心，变易当中有不易，不易当中有简易。无论怎么变都遵守一定的规律，不是胡乱变，是有因必有果。</p><p>六十四卦每一卦要修德，修玄德和福德，福慧双修，世间法的福德和出世间法的玄德。</p><p>玄德就是不离易之本体，就是真心，福德就是根据当下的卦调整自己的起心动念这就是世间法的规律，按照世间法的规律去生活就是福德，每一卦都要守中而行。按照当下的时和位做好自己的本份，这就是适宜，就是中。</p><p>事来则应，怎么应？按照卦德去应，守中用中，最后还要空中，空中就是事去则空，做过了就放下了。</p><p>见卦先见真心，再见相，不要被卦相所转，通过当下的卦指导自己更好的妙用，那就是根据爻辞的指导修德，这就是转化心识，万法唯识，要想转命就要转化自己的心识，也就是自己的念头。</p><p>学习易经就是不断的修德，德重鬼神钦佩。坤卦说积善之家必有余庆，积不善之家必有余殃。这是大智若愚的智慧。</p><p>坤卦修福德，同时也要回归先天之乾，无所住，不居功，知道一切都是生灭的，变化的，无常的，不执着，这就是玄德。</p><p>坤就是空，毕竟空，无所得，所以才能见真心道体，坤卦就是本来无一物，无一物却可以有显化万物的真消息。</p><p>乾卦说，用九，见群龙无首，吉。见群龙无首就见真心，真心无相无不相，不执着任何一法，也不舍弃任何一法，不取不舍，随方应物，应物而不迷。</p><p>坤卦说，先迷后得主，先迷就是我执，就是艮卦，艮就是固执，就是我执，所以不见真心，就丧朋。</p><p>后得主就是西南得朋，西南就是坤，回归坤。坤就是无我，无我就见真我，就得朋。</p><p>易经一直都是在后天里面寻找先天，见真心，同时随缘应物，守中用中空中，体相用合一。</p>',17)]))}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
